'use strict';
/* Blender AI Agent studio — no remote SDK, CDN or artificial demo render claims. */
const $ = (selector) => document.querySelector(selector);
const escapeText = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths = {
  home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',
  script:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>',
  users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v2"/>',
  passport:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="9" cy="10" r="2"/><path d="M6 17c0-3 6-3 6 0M15 9h3M15 13h3"/>',
  cube:'<path d="m12 2 9 5-9 5-9-5 9-5ZM3 7v10l9 5 9-5V7M12 12v10"/>',
  image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',
  camera:'<rect x="3" y="6" width="18" height="15" rx="2"/><circle cx="12" cy="13" r="4"/><path d="M8 6 9 3h6l1 3"/>',
  history:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
  stars:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>',
  settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/>',
  plus:'<path d="M12 4v16M4 12h16"/>',
};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true">${iconPaths[name] || iconPaths.stars}</svg>`}
const sections=[['Главная','home'],['Сценарий','script'],['Персонажи','users'],['Паспорта','passport'],['Реквизит','cube'],['Сцены','image'],['Рендер','camera'],['История','history'],['Настройки','settings']];
let state=null, page='Сценарий', selectedCharacter='',selectedProp='', pendingImage=null, saveTimer=0, saving=false,dirty=false,prepareMessage='',renderState=null,renderPlan=null,studioJob=null;
let providerStatus=null, providerBusy=false;
let approvedMia=null, approvedBusy=false;
let mailboxPolicy=null, mailboxSaving=false;
let trustedUpdateStatus=null, trustedUpdateSaving=false;
let dropboxReviewStatus=null, dropboxReviewSaving=false;
let telegramStatus=null, telegramBusy=false;
let agentRuntime=null, agentRuntimeBusy=false, agentTask=null, agentTaskTimer=0;
function notify(message,error=false){const toast=$('#toast');toast.textContent=message;toast.style.borderColor=error?'#ff8686':'';toast.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>toast.classList.remove('visible'),4200)}
async function api(path,payload){const opts=payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)};let response=await fetch(path,opts);let data=await response.json();if(!response.ok)throw Object.assign(new Error(data.error||`Ошибка ${response.status}`),{code:response.status});return data}
function media(name){return /^[a-f0-9]{32}\.(png|jpg|webp)$/.test(name||'')?'/media/'+name:''}
function imgOrFallback(reference,label){const uri=media(reference);return uri?`<img src="${uri}" alt="${escapeText(label)}" loading="lazy">`:`<span class="placeholder-icon">${escapeText((label||'?').slice(0,1).toUpperCase())}</span>`}
function characterImage(ch){
if(ch?.id==='mia'&&approvedMia?.status==='ready')return `<img src="/api/approved-reference-image/mia" alt="Утверждённый референс Мии" loading="lazy">`;
return imgOrFallback(ch.reference,ch.name);
}
function miaApprovedGallery(ch){
if(ch?.id!=='mia')return '';
const status=approvedMia?.status||'loading';
const ready=status==='ready';
const attached=media(ch.reference)===media('7a3194accfecdb4873bc7d4cd8015edb.jpg');
const desc=status==='loading'?'Проверяем локальный эталон…':ready?'Подтверждён контрольной суммой SHA-256':status==='missing'?'Эталон пока не найден в локальном каталоге episode1/assets/references':'Проверка целостности эталона не пройдена — запрещено использовать файл';
return `<section class="approved-reference-panel" aria-label="Утверждённые референсы Мии">
<h3>Утверждённые референсы Мии</h3>
<p class="hint">Источник: приватная библиотека сезона, один разворот с видами анфас, профиль и со спины. Черновые генерации не используются.</p>
<div class="approved-reference-grid">
<div class="approved-reference-image">${ready?'<img src="/api/approved-reference-image/mia" alt="Утверждённый разворот Мии: анфас, профиль и сзади" loading="lazy">':'<div class="empty-message">Исходный референс пока недоступен</div>'}</div>
<div class="approved-reference-meta">
<p class="section-note"><strong>${escapeText(desc)}</strong></p>
<p class="hint">Статус: ${ready?'утверждённый визуальный эталон': 'требуется локальная синхронизация'}</p>
<p class="hint">Этапы производства:</p>
<ul class="reference-checklist">${(approvedMia?.readiness||[]).map(item=>`<li><span class="${item.status==='ready'?'done':'waiting'}">${item.status==='ready'?'✓':'○'}</span> ${escapeText(item.label)}</li>`).join('')}</ul>
<p class="hint">3D-модель и риг ещё не утверждены. Изображение не считается готовой 3D-моделью.</p>
<button class="btn-secondary" type="button" data-action="link-mia-reference" ${!ready||attached||approvedBusy||saving||dirty?'disabled':''}>${attached?'Эталон закреплён в паспорте':approvedBusy?'Подключение…':'Закрепить этот эталон в паспорте'}</button>
<button class="btn-outline" type="button" data-action="refresh-approved-references">Обновить список референсов</button>
</div></div></section>`;
}
function time(seconds){let s=Math.max(0,Number(seconds)||0);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function uid(prefix){return prefix+'_'+crypto.randomUUID().replaceAll('-','').slice(0,12)}
function activeScene(){return state.scenes.find(scene=>scene.id===state.active_scene)||state.scenes[0]||null}
function markDirty(){dirty=true;$('#savedStatus').textContent='● Не сохранено';clearTimeout(saveTimer);saveTimer=setTimeout(flush,550)}
async function flush(){clearTimeout(saveTimer);if(!state||saving||!dirty)return;saving=true;dirty=false;const snapshot=JSON.parse(JSON.stringify(state));const version=state.revision;$('#savedStatus').textContent='● Сохранение…';try{const saved=await api('/api/state',{revision:version,state:snapshot});state.revision=saved.revision;$('#savedStatus').textContent='✓ Сохранено локально'}catch(error){dirty=true;$('#savedStatus').textContent='● Ошибка сохранения';notify(error.message,true);if(error.code===409){clearTimeout(saveTimer);notify('Другая вкладка изменила проект. Перезагрузи страницу и проверь изменения.',true)}}finally{saving=false;if(dirty&&$('#savedStatus').textContent!=='● Ошибка сохранения')setTimeout(flush,80)}}
function navigation(){return sections.map(([label,ico])=>`<button class="nav ${page===label?'active':''}" data-nav="${label}" title="${label}">${icon(ico)}<span>${label}</span></button>`).join('')}
function draw(){if(!state)return;$('#navigation').innerHTML=navigation();$('#projectTitle').value=state.title;let root=$('#main');if(page==='Сценарий'||page==='Главная')root.innerHTML=dashboard();else if(page==='Персонажи'||page==='Паспорта')root.innerHTML=characterPage();else if(page==='Реквизит')root.innerHTML=propPage();else if(page==='Сцены')root.innerHTML=scenesPage();else if(page==='Рендер')root.innerHTML=renderPage();else if(page==='Настройки')root.innerHTML=providerSettingsPage();else root.innerHTML=historyPage()}
function characterCards(){return state.characters.slice(0,3).map(item=>`<button class="person-tile" data-character="${escapeText(item.id)}"><div class="person-cover">${characterImage(item)}</div><div class="tile-label">${escapeText(item.name)}</div><div class="tile-sub">${escapeText(item.role)}</div></button>`).join('')}
function propCards(){return state.props.slice(0,12).map(item=>`<button class="prop-tile" data-prop="${escapeText(item.id)}"><div class="prop-cover">${imgOrFallback(item.reference,item.name)}</div><div class="prop-caption">${escapeText(item.name)}</div></button>`).join('')}
function sceneCover(scene){if(!scene)return '';const uri=media(scene.preview)||media(state.characters.find(x=>x.id===scene.characters[0])?.reference);return uri?`<img src="${uri}" alt="Референс сцены">`:`<span class="placeholder-icon">${icon('image')}</span>`}
function sceneStrip(){return state.scenes.map((scene,i)=>`<button class="scene-tile ${activeScene()?.id===scene.id?'active':''}" data-scene="${escapeText(scene.id)}"><div class="scene-thumb">${sceneCover(scene)}<span class="index-badge">${i+1}</span><span class="duration-badge">${time(scene.duration)}</span></div><div class="scene-caption"><b>Сцена ${i+1}</b><span class="small">${escapeText(scene.title)}</span></div></button>`).join('')}
function options(values,current){return values.map(value=>`<option value="${escapeText(value)}" ${value===current?'selected':''}>${escapeText(value)}</option>`).join('')}
function dashboard(){const scene=activeScene(),conf=state.settings, total=state.scenes.reduce((sum,item)=>sum+item.duration,0);return `<div class="dashboard">
<section class="column-left">
<div class="card"><div class="card-head"><div class="header-title">${icon('stars')}<h2>Задача агенту</h2></div><span class="muted">•••</span></div><div class="task-content"><textarea class="input" data-bind="task" maxlength="4000" placeholder="Опиши свой сценарий или первую сцену. Агент составит структурированный план для Blender.">${escapeText(state.task)}</textarea><div class="tools"><button class="chip" data-action="load-text">▣ Загрузить сценарий</button><button class="chip" data-nav="Реквизит">▧ Референсы</button><span class="counter" id="taskCounter">${state.task.length}/4000</span></div><button class="btn-primary" data-action="first">✦ &nbsp; Создать первую сцену &nbsp; →</button>${prepareMessage?`<p class="hint">${escapeText(prepareMessage)}</p>`:''}</div></div>
<div class="card"><div class="card-head"><div class="header-title">${icon('users')}<h3>Персонажи</h3></div><button class="icon-link" data-nav="Персонажи">Все персонажи ›</button></div><div class="card-inner"><div class="people-row"><button class="add-tile" data-action="add-character"><span>+</span>Добавить<br>персонажа</button>${characterCards()}</div></div></div>
<div class="card"><div class="card-head"><div class="header-title">${icon('cube')}<h3>Реквизит</h3></div><button class="icon-link" data-nav="Реквизит">Все предметы ›</button></div><div class="card-inner"><div class="props-row">${propCards()}<button class="prop-tile" data-action="add-prop"><div class="prop-cover"><span class="placeholder-icon">+</span></div><div class="prop-caption">Добавить</div></button></div></div></div>
</section>
<section class="column-center"><div class="card preview-card"><div class="card-head"><div class="header-title">${icon('image')}<h2>${scene?escapeText(scene.title):'Сцена 1'}</h2></div><span class="muted">◷ ${time(scene?.duration||conf.duration)}</span></div><div class="preview-area">${sceneCover(scene)||`<div class="empty-preview"><span class="preview-symbol">✧</span><b>Здесь появится первая сцена</b><p>Введи задачу агенту, выбери персонажей и подготовь сцену. Предпросмотр появится после получения реального кадра.</p></div>`}<span class="preview-badge">${scene?(scene.preview?'Референс — не рендер':escapeText(scene.status)):'Сцена не создана'}</span></div><div class="player"><button class="playbtn" title="Плеер будет доступен после рендера" disabled>▶</button><div class="progress"></div><span class="hint">00:00 / ${time(scene?.duration||conf.duration)}</span><span class="chip">${escapeText(conf.aspect)}</span></div></div></section>
<section class="column-right"><div class="card inspector">${inspector()}</div></section>
<section class="card storyboard"><div class="card-head"><div class="header-title">${icon('script')}<h3>Раскадровка (${state.scenes.length} сцен)</h3></div><span class="hint">Сохранение на этом компьютере</span></div><div class="storyboard-flex"><div class="scene-strip">${sceneStrip()}<button class="add-tile add-scene" data-action="add-scene"><span>+</span>Добавить сцену</button></div><div class="summary"><div class="summary-top"><div><div class="small muted">Общая длительность</div><div class="small muted">${state.scenes.length} сцен</div></div><strong>${time(total)}</strong></div><button class="btn-primary" data-nav="Рендер">▶ &nbsp; Рендер и проверка Blender</button></div></div></section></div>`}
function inspector(){const scene=activeScene(),cfg=state.settings;return `<div class="card-head"><div class="header-title">${icon('settings')}<h2>Настройки сцены</h2></div></div><div class="field"><label class="label">Название сцены</label><input class="input" data-scene-field="title" maxlength="180" value="${escapeText(scene?.title||'Первая сцена')}" ${scene?'':'disabled'}></div><div class="field"><label class="label">Описание сцены</label><textarea class="input" data-scene-field="prompt" maxlength="3000" ${scene?'':'disabled'} placeholder="Задача сцены">${escapeText(scene?.prompt||'')}</textarea></div>
${settingSelect('style','Стиль',[cfg.style,'3D-анимация','Кинематографичный','Мультфильм','Реалистичный'])}
${settingSelect('camera','Камера',[cfg.camera,'Плавное слежение','Статичная','Панорама','Приближение'])}
${settingSelect('animation','Анимация',[cfg.animation,'Естественное движение','Покадровая','Плавная'])}
<div class="setting-line"><label>Длительность</label><input type="number" class="input" min="1" max="120" data-setting="duration" value="${scene?scene.duration:cfg.duration}"></div>
${settingSelect('aspect','Формат',['9:16','16:9','1:1'])}
${settingSelect('resolution','Разрешение',['360x640','640x360','512x512','720x1280','1280x720'])}
<div class="setting-line"><label>Частота кадров</label><input type="number" min="1" max="60" class="input" data-setting="fps" value="${cfg.fps}"></div>
${settingSelect('sound','Звук',[cfg.sound,'Отдельное аудио','Без звука'])}
<p class="section-note">Сценарий и параметры сохраняются локально. Для реального персонажа необходим 3D-риг. Тестовый персонаж выполняет ограниченные действия в Blender без облака.</p><button class="btn-primary" data-action="prepare">✦ &nbsp; Проверить команды сцены</button>`}
function settingSelect(field,label,choices){let cfg=state.settings;let unique=[...new Set(choices)];return `<div class="setting-line"><label>${escapeText(label)}</label><select class="input" data-setting="${field}">${options(unique,cfg[field])}</select></div>`}
function header(title,subtitle,button,action){return `<div class="page-heading"><div><h1>${escapeText(title)}</h1><p>${escapeText(subtitle)}</p></div>${button?`<button class="btn-primary" style="width:auto" data-action="${action}">${escapeText(button)}</button>`:''}</div>`}
function charactersList(){return state.characters.map(ch=>`<button class="asset-card ${selectedCharacter===ch.id?'active':''}" data-character="${escapeText(ch.id)}"><div class="asset-image">${characterImage(ch)}</div><strong>${escapeText(ch.name)}</strong><small>${escapeText(ch.role)}</small></button>`).join('')}
function characterPage(){if(!selectedCharacter)selectedCharacter=state.characters[0]?.id||'';const ch=state.characters.find(x=>x.id===selectedCharacter);const isPassport=page==='Паспорта';return `${header(isPassport?'Паспорта персонажей':'Персонажи','Карточки, внешний вид и постоянные характеристики героев','+ Добавить персонажа','add-character')}<div class="page-grid"><section class="card"><div class="card-head"><h2>Библиотека персонажей</h2><span class="hint">${state.characters.length} записей</span></div><div class="asset-grid">${charactersList()}</div></section><section class="card"><div class="editor-content">${!ch?'<p class="empty-message">Добавь первого персонажа, чтобы открыть паспорт.</p>':`<h2 class="editor-title">Паспорт персонажа · ${escapeText(ch.name)}</h2><div class="media-control"><div class="avatar-preview">${characterImage(ch)}</div><div><p class="hint">Референс персонажа хранится локально.<br>Рекомендуется добавить изображение с устойчивой внешностью.</p><button class="btn-secondary" data-action="image-character">Загрузить референс</button></div></div>${miaApprovedGallery(ch)}${textField('name','Имя',ch.name,'character',100)}${textField('role','Роль',ch.role,'character',120)}${textField('age','Возраст',ch.age,'character',80)}${textArea('traits','Характер и привычки',ch.traits,'character',900)}${textArea('appearance','Внешность / постоянные признаки',ch.appearance,'character',1200)}${textArea('outfit','Одежда',ch.outfit,'character',900)}${textField('voice','Голос / манера речи',ch.voice,'character',200)}<div class="editor-buttons"><button class="btn-secondary" data-nav="Сценарий">Перейти к сценарию →</button><button class="btn-outline danger" data-action="delete-character">Удалить персонажа</button></div>`}</div></section></div>`}
function textField(field,label,value,kind,max){return `<div class="field"><label class="label">${escapeText(label)}</label><input class="input" data-${kind}-field="${field}" maxlength="${max}" value="${escapeText(value)}"></div>`}
function textArea(field,label,value,kind,max){return `<div class="field"><label class="label">${escapeText(label)}</label><textarea class="input" data-${kind}-field="${field}" maxlength="${max}">${escapeText(value)}</textarea></div>`}
function propsList(){return state.props.map(p=>`<button class="asset-card ${selectedProp===p.id?'active':''}" data-prop="${escapeText(p.id)}"><div class="asset-image">${imgOrFallback(p.reference,p.name)}</div><strong>${escapeText(p.name)}</strong><small>${escapeText(p.kind)}</small></button>`).join('')}
function propPage(){if(!selectedProp)selectedProp=state.props[0]?.id||'';const prop=state.props.find(x=>x.id===selectedProp);return `${header('Реквизит и окружение','Предметы, фоны и локации для будущих сцен','+ Добавить реквизит','add-prop')}<div class="page-grid"><section class="card"><div class="card-head"><h2>Библиотека проекта</h2><span class="hint">${state.props.length} объектов</span></div><div class="asset-grid">${propsList()}</div></section><section class="card"><div class="editor-content">${!prop?'<p class="empty-message">Пока нет объектов.</p>':`<h2 class="editor-title">Карточка реквизита · ${escapeText(prop.name)}</h2><div class="media-control"><div class="avatar-preview">${imgOrFallback(prop.reference,prop.name)}</div><button class="btn-secondary" data-action="image-prop">Загрузить референс</button></div>${textField('name','Название',prop.name,'prop',120)}${textField('kind','Категория',prop.kind,'prop',100)}${textArea('description','Описание и постоянные признаки',prop.description,'prop',1500)}<div class="editor-buttons"><button class="btn-secondary" data-nav="Сценарий">Перейти к сценарию →</button><button class="btn-outline danger" data-action="delete-prop">Удалить реквизит</button></div>`}</div></section></div>`}
function scenesPage(){const scene=activeScene();return `${header('Сцены и раскадровка','Список сцен с выбранными персонажами, реквизитом и постановкой','+ Добавить сцену','add-scene')}<div class="page-grid"><section class="card"><div class="card-head"><h2>Эпизоды (${state.scenes.length})</h2></div><div class="asset-grid">${state.scenes.map((s,i)=>`<button class="asset-card ${s.id===scene?.id?'active':''}" data-scene="${escapeText(s.id)}"><div class="asset-image">${sceneCover(s)}</div><strong>${i+1}. ${escapeText(s.title)}</strong><small>${time(s.duration)} · ${escapeText(s.status)}</small></button>`).join('')||'<div class="empty-message">Создай первую сцену на вкладке «Сценарий».</div>'}</div></section><section class="card"><div class="editor-content">${scene?`<h2 class="editor-title">Сцена · ${escapeText(scene.title)}</h2>${textField('title','Название',scene.title,'scene',180)}${textArea('prompt','Действия по сценарию',scene.prompt,'scene',3000)}${textField('location','Локация',scene.location,'scene',600)}${textField('camera','Камера',scene.camera,'scene',600)}${textField('style','Стиль',scene.style,'scene',200)}${textField('animation','Анимация',scene.animation,'scene',200)}<div class="field"><label class="label">Длительность (секунды)</label><input class="input" type="number" min="1" max="120" data-scene-field="duration" value="${scene.duration}"></div><div class="field"><label class="label">Участники</label><div class="tools">${state.characters.map(ch=>`<label class="chip"><input type="checkbox" data-member="characters" value="${escapeText(ch.id)}" ${scene.characters.includes(ch.id)?'checked':''}> ${escapeText(ch.name)}</label>`).join('')}</div></div><div class="field"><label class="label">Реквизит</label><div class="tools">${state.props.map(p=>`<label class="chip"><input type="checkbox" data-member="props" value="${escapeText(p.id)}" ${scene.props.includes(p.id)?'checked':''}> ${escapeText(p.name)}</label>`).join('')}</div></div><div class="media-control"><div class="avatar-preview">${sceneCover(scene)}</div><button class="btn-secondary" data-action="image-scene">Загрузить референс сцены</button></div><div class="editor-buttons"><button class="btn-primary" style="width:auto" data-action="prepare">Подготовить план</button><button class="btn-outline danger" data-action="delete-scene">Удалить сцену</button></div>`:'<p class="empty-message">Пока нет сцен. Перейди к сценарию и сформулируй задачу для агента.</p>'}</div></section></div>`}
function renderPage(){const scene=activeScene();const ready=!!scene&&renderPlan?.scene_id===scene.id&&renderPlan?.readiness==='ready_fixture';return `${header('Генерация сцены Blender','Интерпретация команды → проверка ресурсов → реальные кадры → MP4')}<div class="info-bar"><strong>Локальный режим.</strong> Поддерживаются простые русские действия тестового персонажа; реальные персонажи без 3D-рига не подменяются геометрическими заглушками. Для проверки введи: «Тестовый персонаж идёт, поворачивается и говорит. Камера следует».</div><div class="page-grid"><section class="card"><div class="editor-content"><h2 class="editor-title">${scene?escapeText(scene.title):'Выбери сцену'}</h2>${scene?`<p class="hint">${escapeText(scene.prompt)}</p><button class="btn-secondary" data-action="interpret-scene">Проверить команду и ресурсы</button>${renderPlan?`<p class="section-note">Персонаж: ${escapeText(renderPlan.label)}<br>Действия: ${escapeText(renderPlan.actions.join(', '))}<br>Камера: ${escapeText(renderPlan.camera)}<br>Готовность: ${escapeText(renderPlan.readiness)}</p>${renderPlan.missing_requirements.map(x=>`<p class="hint">Требуется: ${escapeText(x)}</p>`).join('')}`:''}<button class="btn-primary" data-action="render-scene" ${!ready?'disabled':''}>▶ &nbsp; Сгенерировать сцену</button><button class="btn-secondary" data-action="assemble-project">Собрать готовые сцены в один MP4</button>`:'<p class="hint">Сначала создай сцену в разделе «Сценарий».</p>'}</div></section><section class="card"><div class="editor-content"><h2 class="editor-title">Последняя задача Blender</h2><p class="section-note" id="studioJobMessage">${escapeText(studioJob?.message||'Рендер ещё не запускался')}</p><p class="hint">${studioJob?`Статус: ${escapeText(studioJob.state)} · ${studioJob.rendered_frames}/${studioJob.total_frames} кадров · ${studioJob.progress_percent}%`:'После запуска появятся фактические кадры и состояние задачи.'}</p>${studioJob?.state==='completed'?`<video class="render-video" controls src="${studioJob.video_url}"></video>`:''}${studioJob?.state==='running'?'<button class="btn-secondary" data-action="cancel-scene">Остановить рендер</button>':''}<p class="hint">Результаты сохраняются локально, в каталоге studio_jobs. Тестовая геометрия не является готовой моделью Мии.</p></div></section>${agentTaskPanel()}</div>`}

function providerSettingsPage(){
const ready=providerStatus?.configured===true;
const status=providerStatus===null?'Загрузка состояния…':ready?'Ключ сохранён':'Ключ ещё не сохранён';
return `${header('Настройки подключений','Замена ключа OctavAPI без переустановки агента и повторной настройки GitHub')}
<section class="card credential-card"><div class="card-head"><div class="header-title">${icon('settings')}<h2>OctavAPI · доступ к модели</h2></div><span class="hint">Опциональный внешний сервис</span></div>
<div class="editor-content"><p id="octavaStatus" class="credential-status" role="status">${escapeText(status)}</p>
<div class="field"><label class="label" for="octavaKey">Вставить новый API-ключ</label>
<input id="octavaKey" class="input" type="password" inputmode="text" autocomplete="off" autocapitalize="off" spellcheck="false" maxlength="2048" placeholder="Вставьте ключ сюда"></div>
<button class="btn-primary credential-save" type="button" data-action="save-octava-key" ${providerBusy?'disabled':''}>${providerBusy?'Проверка подключения…':'ОК · Проверить и сохранить'}</button>
<p class="section-note">При сохранении выполняется короткий платный запрос к OctavAPI. Если новый ключ не работает, текущий останется неизменным. Ключ хранится в защищённом хранилище Windows, не в проекте, браузере или GitHub.</p>
<p class="section-note">GitHub подключён отдельным токеном: окончание токенов OctavAPI не отключает получение и отправку задач через GitHub. После замены ключ применяется к новым запросам без перезапуска.</p>
<div class="field"><label class="label" for="octavaModelSelect">Основная модель для новых запросов</label>
<select class="input" id="octavaModelSelect" ${providerBusy||!ready?'disabled':''}>
<option value="gpt-6-luna" ${providerStatus?.model==='gpt-6-luna'?'selected':''}>GPT-6 Luna · экономичная</option>
<option value="gpt-6.1-sol" ${providerStatus?.model==='gpt-6.1-sol'?'selected':''}>GPT-6.1 Sol · сложные задачи</option>
</select></div>
<button class="btn-secondary" type="button" data-action="save-octava-model" ${providerBusy||!ready?'disabled':''}>${providerBusy?'Проверка…':'Проверить модель и применить'}</button>
<p class="section-note">При переключении выполняется один платный проверочный запрос; при ошибке прежний выбор сохраняется. API-ключ и память проекта не изменяются. Для отдельных задач доступен режим Luna.</p>
</div></section>
<section class="card credential-card"><div class="card-head"><div class="header-title">${icon('settings')}<h2>GitHub · автономное выполнение</h2></div><span class="hint">Разрешение сохраняется только на этом компьютере</span></div>
<div class="editor-content">
<p class="credential-status" role="status">${mailboxPolicy===null?'Загрузка…':mailboxPolicy.enabled?'Автономный режим включён':'Автономный режим выключен'}</p>
${mailboxOption('enabled','Выполнять доверенные задания GitHub без подтверждения YES','Диагностика, проверка Blender, чтение ресурсов и компиляция плана сцены')}
${mailboxOption('allow_blender','Разрешить создание тестовых Blender-сцен','Ограниченные задачи в рабочей папке: 3D-заготовки и сохранение плана')}
${mailboxOption('allow_asset_sync','Разрешить синхронизацию утверждённых ассетов','Только файлы из закреплённого манифеста; SHA-256 и сохранение существующих файлов')}
${mailboxOption('allow_tests','Разрешить автоматические тесты Python','Только уже установленный код; запуск тестов может занимать время')}
${mailboxOption('allow_octava','Разрешить короткие запросы OctavAPI','Без локального суточного лимита: провайдер может списывать оплату за каждый запрос')}
<button class="btn-primary credential-save" type="button" data-action="save-mailbox-policy" ${mailboxSaving?'disabled':''}>${mailboxSaving?'Сохранение…':'Сохранить разрешения'}</button>
<p class="section-note">Произвольные команды и неподтверждённые патчи заблокированы. Доверенные обновления программы разрешаются отдельным переключателем ниже.</p></div></section>
<section class="card credential-card"><div class="card-head"><div class="header-title">${icon('settings')}<h2>GitHub · автоматические исправления программы</h2></div><span class="hint">Отдельное локальное разрешение</span></div><div class="editor-content">
<p class="credential-status" role="status">${trustedUpdateStatus===null?'Загрузка…':trustedUpdateStatus.enabled?'Доверенные обновления разрешены':'Автоматические обновления выключены'}</p>
<label class="mailbox-option"><input type="checkbox" id="trustedUpdateEnabled" ${trustedUpdateStatus?.enabled?'checked':''}><span><b>Разрешить проверенные обновления агента без YES</b><small>Только файлы из закреплённого коммита моего репозитория GitHub, с проверкой SHA-256, резервной копией, тестами и откатом. Обновление кода может выполнять новые локальные функции от имени твоего Windows-пользователя.</small></span></label>
<button class="btn-primary credential-save" type="button" data-action="save-trusted-updates" ${trustedUpdateSaving?'disabled':''}>${trustedUpdateSaving?'Сохранение…':'Сохранить разрешение на обновления'}</button>
<p class="section-note">Разрешение по умолчанию выключено и хранится только на компьютере. Неизвестные адреса, произвольные команды и изменения файлов ключей запрещены. При сетевой ошибке установленная версия сохраняется.</p></div></section>
<section class="card credential-card"><div class="card-head"><div class="header-title">${icon('camera')}<h2>Dropbox · проверка сцен</h2></div><span class="hint">Синхронизация видео с ChatGPT</span></div>
<div class="editor-content">
<p class="credential-status" role="status">${dropboxReviewStatus===null?'Проверка Dropbox…':dropboxReviewStatus.desktop_folder_detected?'Dropbox Desktop найден':'Папка Dropbox Desktop пока не найдена'}</p>
<label class="mailbox-option"><input type="checkbox" id="dropboxReviewEnabled" ${dropboxReviewStatus?.enabled?'checked':''}><span><b>Автоматически экспортировать тестовые сцены для проверки</b><small>После успешного рендера копируются сжатый MP4, 12 ключевых кадров и параметры камеры в папку AI-Agent-Reviews синхронизируемого Dropbox. Файлы могут попасть в облако Dropbox; на этапе проверки их получит ChatGPT с подключённым Dropbox. Оригиналы Blender остаются на ПК.</small></span></label>
<button class="btn-primary credential-save" type="button" data-action="save-dropbox-review" ${dropboxReviewSaving?'disabled':''}>${dropboxReviewSaving?'Сохранение…':'Сохранить настройки Dropbox'}</button>
<p class="section-note">Опция по умолчанию выключена. Dropbox Desktop должен быть установлен и авторизован. Синхронизацию с облаком проверяем отдельно; она не подтверждается одним фактом создания локальной копии. Для ограничения места новые публикации прекращаются после 40 тестов, старые файлы автоматически не удаляются.</p>
</div></section>
<section class="card credential-card"><div class="card-head"><div class="header-title">${icon('history')}<h2>Telegram · уведомления на телефон</h2></div><span class="hint">Бесплатные личные сообщения</span></div>
<div class="editor-content">
<p class="credential-status" role="status">${telegramStatus?.paired?'Telegram подключён':telegramStatus?.configured?'Токен сохранён. Ожидаем /start в личном чате':'Telegram ещё не подключён'}</p>
<div class="telegram-alert-control">
 <div><b>Отправка уведомлений</b><p class="section-note">Включает или выключает все автоматические сообщения Telegram. Если новых заданий GitHub нет 10 минут, агент пришлёт одно предупреждение за период простоя. При отключении накопленные уведомления удаляются.</p></div>
 <button type="button" class="btn-primary credential-save" data-action="telegram-notify-toggle" ${telegramBusy||!telegramStatus?'disabled':''} aria-pressed="${telegramStatus?.notifications_enabled!==false}">${telegramStatus?.notifications_enabled===false?'Включить уведомления':'Выключить уведомления'}</button>
</div>
<label class="mailbox-option"><input type="checkbox" id="telegramUseRelay" ${telegramStatus?.use_relay?'checked':''}><span><b>Использовать мой Render для доступа к Telegram</b><small>Нужно, если Telegram API недоступен напрямую с Windows. При включении бот-токен, содержимое сообщений и ответы Telegram будут проходить через отдельный HTTPS-сервис Render в моём аккаунте. Настройка по умолчанию выключена.</small></span></label>
<button class="btn-primary credential-save" type="button" data-action="telegram-route" ${telegramBusy?'disabled':''}>Сохранить способ подключения</button>
<div class="field"><label class="label" for="telegramBotToken">Токен нового бота из @BotFather</label>
<input id="telegramBotToken" class="input" type="password" autocomplete="off" autocapitalize="off" spellcheck="false" maxlength="160" placeholder="Вставьте токен только здесь"></div>
<button class="btn-primary credential-save" type="button" data-action="telegram-save" ${telegramBusy?'disabled':''}>Сохранить токен бота</button>
<p class="section-note">В Telegram откройте своего бота и отправьте ему команду /start, затем нажмите «Привязать личный чат». Токен хранится только в защищённом хранилище Windows и никогда не отправляется в GitHub.</p>
<div class="row gap-2"><button class="btn-primary credential-save" type="button" data-action="telegram-pair" ${telegramBusy||!telegramStatus?.configured?'disabled':''}>Привязать личный чат</button>
<button class="btn-primary credential-save" type="button" data-action="telegram-test" ${telegramBusy||!telegramStatus?.paired?'disabled':''}>Отправить тест в Telegram</button></div>
<p class="section-note">При включённой отправке будут приходить уведомления о сценах, ошибках, обновлениях и отсутствии новых задач 10 минут. Во время недоступности Telegram сообщения ставятся в локальную очередь. Выключение отправки очищает эту очередь.</p>
</div></section>
<section class="card credential-card"><div class="card-head"><div class="header-title"><h2>Управление Windows-агентом</h2></div></div>
<div class="editor-content">
<p class="credential-status" role="status">${agentRuntime?.paused?'Приём новых задач приостановлен':'Приём заданий активен'}${agentRuntime?.restart_pending?' · Ожидается перезапуск':''}</p>
<div class="row gap-2">
<button class="btn-primary credential-save" type="button" data-action="agent-toggle-pause" ${agentRuntimeBusy||!agentRuntime?'disabled':''}>${agentRuntime?.paused?'Возобновить задачи':'Приостановить задачи'}</button>
<button class="btn-primary credential-save" type="button" data-action="agent-force-restart" ${agentRuntimeBusy||!agentRuntime?'disabled':''}>Принудительно перезапустить агент</button>
</div>
<p class="section-note">Команда перезапуска действует только на Studio и GitHub-агент под управлением Windows-supervisor. Активный рендер не прерывается; перезапуск выполнится после его завершения. Если supervisor остановлен, команда останется в локальном файле до его восстановления.</p>
<p class="section-note">Команды Telegram: /status, /tasks, /logs, /pause, /resume, /restart, /notifications_on, /notifications_off, /help. Доступ разрешён только из привязанного личного чата.</p>
</div></section>`;}
function mailboxOption(key,title,help){return `<label class="mailbox-option"><input type="checkbox" data-mailbox-option="${key}" ${mailboxPolicy?.[key]?'checked':''}><span><b>${escapeText(title)}</b><small>${escapeText(help)}</small></span></label>`}
async function refreshAgentRuntime(){try{agentRuntime=await api('/api/agent-runtime');if(page==='Настройки'&&!agentRuntimeBusy)draw()}catch(error){if(page==='Настройки')notify(error.message,true)}}
async function agentPause(){if(agentRuntimeBusy||!agentRuntime)return;agentRuntimeBusy=true;try{const result=await api('/api/agent-pause',{paused:!agentRuntime.paused});agentRuntime={...agentRuntime,paused:result.paused};notify(result.paused?'Поступление задач приостановлено.':'Приём задач возобновлён.')}catch(error){notify(error.message,true)}finally{agentRuntimeBusy=false;draw()}}
async function agentRestart(){if(agentRuntimeBusy||!agentRuntime)return;agentRuntimeBusy=true;try{const result=await api('/api/agent-restart',{});agentRuntime={...agentRuntime,restart_pending:result.restart_pending};notify('Запрос перезапуска сохранён. Supervisor выполнит его безопасно.')}catch(error){notify(error.message,true)}finally{agentRuntimeBusy=false;draw()}}
async function refreshTelegramStatus(){try{telegramStatus=await api('/api/telegram-status');if(page==='Настройки'&&!telegramBusy)draw()}catch(error){if(page==='Настройки')notify(error.message,true)}}
async function telegramRoute(){if(telegramBusy)return;const checked=Boolean($('#telegramUseRelay')?.checked);telegramBusy=true;try{const v=await api('/api/telegram-transport',{use_relay:checked});telegramStatus={...telegramStatus,use_relay:v.use_relay};notify(checked?'Telegram: выбран безопасный HTTPS-маршрут через Render.':'Telegram: прямое подключение.')}catch(error){notify(error.message,true)}finally{telegramBusy=false;draw()}}
async function telegramSave(){if(telegramBusy)return;const field=$('#telegramBotToken');let token=field?.value.trim()||'';if(field)field.value='';if(!token)return notify('Нужен токен от BotFather',true);telegramBusy=true;try{telegramStatus=await api('/api/telegram-configure',{bot_token:token});notify('Бот проверен. Отправьте ему /start, затем привяжите чат.')}catch(error){notify(error.message,true)}finally{token='';telegramBusy=false;draw()}}
async function telegramPair(){if(telegramBusy)return;telegramBusy=true;try{telegramStatus=await api('/api/telegram-pair',{});notify('Личный Telegram подключён. Проверочное сообщение отправлено.')}catch(error){notify(error.message,true)}finally{telegramBusy=false;draw()}}
async function telegramTest(){if(telegramBusy)return;telegramBusy=true;try{await api('/api/telegram-test',{});notify('Тестовое сообщение отправлено в Telegram.')}catch(error){notify(error.message,true)}finally{telegramBusy=false;draw()}}
async function telegramToggleNotifications(){if(telegramBusy||!telegramStatus)return;const enabled=telegramStatus.notifications_enabled===false;telegramBusy=true;try{const result=await api('/api/telegram-notifications',{enabled});telegramStatus={...telegramStatus,notifications_enabled:result.notifications_enabled,enabled:Boolean(telegramStatus.paired&&result.notifications_enabled)};notify(enabled?'Уведомления Telegram включены.':'Уведомления Telegram выключены, ожидающие сообщения удалены.')}catch(error){notify(error.message,true)}finally{telegramBusy=false;draw()}}
async function refreshDropboxReview(){try{dropboxReviewStatus=await api('/api/dropbox-review');if(page==='Настройки'&&!dropboxReviewSaving)draw()}catch(error){notify(error.message,true)}}
async function saveDropboxReview(){if(dropboxReviewSaving)return;const enabled=Boolean($('#dropboxReviewEnabled')?.checked);dropboxReviewSaving=true;try{dropboxReviewStatus=await api('/api/dropbox-review',{enabled});notify(enabled?'Экспорт тестовых сцен в Dropbox разрешён.':'Экспорт в Dropbox выключен.')}catch(error){notify(error.message,true)}finally{dropboxReviewSaving=false;draw()}}
async function refreshTrustedUpdates(){try{trustedUpdateStatus=await api('/api/trusted-updates');if(page==='Настройки'&&!trustedUpdateSaving)draw()}catch(error){notify(error.message,true)}}
async function saveTrustedUpdates(){if(trustedUpdateSaving)return;const enabled=Boolean($('#trustedUpdateEnabled')?.checked);trustedUpdateSaving=true;try{trustedUpdateStatus=await api('/api/trusted-updates',{enabled});notify(enabled?'Проверенные обновления разрешены: новые задания больше не потребуют установки вручную.':'Автоматические обновления запрещены')}catch(error){notify(error.message,true)}finally{trustedUpdateSaving=false;draw()}}
async function refreshMailboxPolicy(){try{mailboxPolicy=await api('/api/mailbox-policy');if(page==='Настройки'&&!mailboxSaving)draw()}catch(error){notify(error.message,true)}}
async function saveMailboxPolicy(){if(mailboxSaving)return;const value={};for(const name of ['enabled','allow_blender','allow_asset_sync','allow_tests','allow_octava'])value[name]=Boolean(document.querySelector('[data-mailbox-option="'+name+'"]')?.checked);mailboxSaving=true;try{mailboxPolicy=await api('/api/mailbox-policy',value);notify(value.enabled?'Автономная обработка разрешена. Перезапуск агента нужен только для обновления кода.':'Автономная обработка выключена.')}catch(error){notify(error.message,true)}finally{mailboxSaving=false;draw()}}

async function refreshApprovedReferences(){try{const data=await api('/api/approved-references');approvedMia=data.references?.find(x=>x.character_id==='mia')||null;if(page==='Паспорта'||page==='Персонажи')draw()}catch(error){notify(error.message,true)}}
async function linkApprovedMiaReference(){
if(approvedBusy||dirty||saving)return notify('Дождись сохранения изменений паспорта',true);
approvedBusy=true;draw();
try{state=await api('/api/link-mia-reference',{revision:state.revision});notify('Утверждённый разворот Мии закреплён в паспорте.');}
catch(error){notify(error.message,true)}finally{approvedBusy=false;draw()}
}
async function refreshOctavaStatus(){try{providerStatus=await api('/api/octava-key');if(page==='Настройки'&&!providerBusy)draw()}catch(error){if(page==='Настройки')notify(error.message,true)}}
async function saveOctavaModel(){
const selected=$('#octavaModelSelect')?.value;
if(providerBusy||!['gpt-6-luna','gpt-6.1-sol'].includes(selected))return;
if(selected===providerStatus?.model)return notify('Эта модель уже используется.');
providerBusy=true;draw();
try{providerStatus=await api('/api/octava-model',{model:selected});notify('Модель проверена и выбрана для новых задач.')}
catch(error){notify(error.message,true)}
finally{providerBusy=false;draw();if(page==='Настройки')refreshOctavaStatus()}
}
async function saveOctavaKey(){
const field=$('#octavaKey');if(!field||providerBusy)return;
let key=field.value;field.value='';
if(!key.trim()){key='';return notify('Вставьте новый ключ OctavAPI',true)}
providerBusy=true;draw();
try{providerStatus=await api('/api/octava-key',{api_key:key});notify('Новый ключ проверен и сохранён. Перезапуск не нужен.')}
catch(error){notify(error.message,true)}
finally{key='';providerBusy=false;draw();if(page==='Настройки')refreshOctavaStatus()}
}
function historyPage(){return `${header('История проекта','Сохранённые записи и последние операции текущей сессии')}<div class="card"><div class="card-head"><h2>Сцены проекта</h2></div>${state.scenes.map((s,i)=>`<button class="history-item" data-scene="${escapeText(s.id)}" style="width:100%;border:0;border-bottom:1px solid #264153;text-align:left;color:inherit;background:transparent"><span>${i+1}. ${escapeText(s.title)}</span><span class="muted">${escapeText(s.status)} · ${time(s.duration)}</span></button>`).join('')||'<p class="empty-message">История пока пуста: ещё не создано ни одной сцены.</p>'}</div><div class="info-bar" style="margin-top:12px">История рендеров будет расширена после подключения исполнительного модуля. Сейчас программа не придумывает несуществующие генерации.</div>`}
function createCharacter(){if(state.characters.length>=60)return notify('Достигнут лимит персонажей',true);const id=uid('char');state.characters.push({id,name:'Новый персонаж',role:'Второстепенный',age:'',traits:'',appearance:'',outfit:'',voice:'',reference:''});selectedCharacter=id;page='Паспорта';markDirty();draw()}
function createProp(){if(state.props.length>=200)return notify('Достигнут лимит реквизита',true);const id=uid('prop');state.props.push({id,name:'Новый предмет',kind:'Реквизит',description:'',reference:''});selectedProp=id;page='Реквизит';markDirty();draw()}
function createScene(){if(state.scenes.length>=80)return notify('Достигнут лимит сцен',true);const id=uid('scene');const index=state.scenes.length+1;state.scenes.push({id,title:`Сцена ${index}`,prompt:index===1?state.task:'',location:'',camera:state.settings.camera,style:state.settings.style,animation:state.settings.animation,status:'черновик',preview:'',duration:state.settings.duration,characters:state.characters.slice(0,3).map(c=>c.id),props:[]});state.active_scene=id;renderPlan=null;markDirty();draw()}
async function firstScene(){if(!state.task.trim())return notify('Сначала введи сценарий в поле «Задача агенту».',true);if(!state.scenes.length)createScene();else {const active=activeScene();if(active)active.prompt=state.task;markDirty()}await interpretScene();page='Рендер';draw()}
async function prepare(){await interpretScene()}
async function interpretScene(){await flush();if(dirty)return;const scene=activeScene();if(!scene)return notify('Выбери сцену',true);try{renderPlan=await api('/api/interpret',{revision:state.revision,scene_id:scene.id});prepareMessage=renderPlan.missing_requirements.join('; ')||'Поддерживаемые команды распознаны';scene.status=renderPlan.readiness==='ready_fixture'?'план готов':'ошибка';markDirty();await flush();notify(renderPlan.readiness==='ready_fixture'?'Сцена готова к тестовому рендеру':prepareMessage,renderPlan.readiness!=='ready_fixture')}catch(error){renderPlan=null;notify(error.message,true)}}
async function startStudioRender(){await flush();if(dirty)return;try{const scene=activeScene();if(!scene)return notify('Сцена не выбрана',true);studioJob=await api('/api/render-scene',{revision:state.revision,scene_id:scene.id});draw();pollStudioJob()}catch(error){notify(error.message,true)}}
async function pollStudioJob(){if(!studioJob?.job_id)return;try{studioJob=await api('/api/studio-job/'+studioJob.job_id);if(page==='Рендер')draw();if(studioJob.state==='queued'||studioJob.state==='running')setTimeout(pollStudioJob,2000)}catch(error){notify(error.message,true)}}
async function assembleProject(){await flush();if(dirty)return;try{studioJob=await api('/api/render-project',{revision:state.revision});draw();pollStudioJob()}catch(error){notify(error.message,true)}}
async function cancelStudioRender(){if(!studioJob?.job_id)return;try{await api('/api/cancel-scene',{job_id:studioJob.job_id});pollStudioJob()}catch(error){notify(error.message,true)}}

function removeSelected(kind){renderPlan=null;let item=kind==='character'?state.characters.find(x=>x.id===selectedCharacter):kind==='prop'?state.props.find(x=>x.id===selectedProp):activeScene();if(!item||!confirm(`Удалить «${item.name||item.title}»?`))return;if(kind==='character'){state.characters=state.characters.filter(x=>x.id!==item.id);state.scenes.forEach(s=>s.characters=s.characters.filter(id=>id!==item.id));selectedCharacter=state.characters[0]?.id||''}else if(kind==='prop'){state.props=state.props.filter(x=>x.id!==item.id);state.scenes.forEach(s=>s.props=s.props.filter(id=>id!==item.id));selectedProp=state.props[0]?.id||''}else{state.scenes=state.scenes.filter(x=>x.id!==item.id);state.active_scene=state.scenes[0]?.id||''}markDirty();draw()}
async function uploadImage(){let f=$('#imageFile').files[0];if(!f||!pendingImage)return;if(f.size>3_000_000)return notify('Максимальный размер изображения — 3 МБ.',true);const extension=f.type==='image/png'?'png':f.type==='image/jpeg'?'jpg':f.type==='image/webp'?'webp':null;if(!extension)return notify('Поддерживаются PNG, JPEG и WEBP.',true);try{const data=await new Promise((resolve,reject)=>{let r=new FileReader();r.onerror=()=>reject(new Error('Не удалось прочитать изображение'));r.onload=()=>resolve(String(r.result).split(',')[1]);r.readAsDataURL(f)});const response=await api('/api/image',{extension,data});let target=pendingImage.kind==='character'?state.characters.find(x=>x.id===pendingImage.id):pendingImage.kind==='prop'?state.props.find(x=>x.id===pendingImage.id):state.scenes.find(x=>x.id===pendingImage.id);if(!target)return notify('Карточка уже удалена',true);target[pendingImage.kind==='scene'?'preview':'reference']=response.filename;markDirty();draw();notify('Референс сохранён локально')}catch(error){notify(error.message,true)}finally{$('#imageFile').value='';pendingImage=null}}
async function renderDemo(){const source=$('#renderSource')?.value.trim();const lens=Number($('#renderLens')?.value);if(!source)return notify('Укажи путь к .blend',true);try{localStorage.setItem('blenderSource',source);renderState=await api('/api/demo-render',{source,lens});draw();notify('Запущен технический тест Blender');pollRender()}catch(error){notify(error.message,true)}}
async function pollRender(){try{renderState=await api('/api/render-status');if(page==='Рендер'){$('#renderMessage').textContent=renderState.message;$('#renderOutput').textContent=renderState.output||'Появится после запуска';$('#renderLog').textContent=renderState.log||'Появится после запуска'}if(renderState.state==='running')setTimeout(pollRender,2000);else if(page==='Рендер')draw()}catch(error){notify(error.message,true)}}
function agentTaskPanel(){
const stateText=agentTask?.state==='running'?'Задача выполняется':agentTask?.state==='cancelling'?'Остановка запрошена':agentTask?.state==='unavailable'?'Статус агента недоступен':'Очередь агента свободна';
const detail=agentTask?.task_id?'ID: '+agentTask.task_id+' · '+(agentTask.project_name||agentTask.operation||''):'Отображается активная задача удалённого агента.';
const cancel=agentTask?.state==='running'?'<button class="btn-secondary" data-action="cancel-agent-task">Отменить задачу агента</button>':'';
return '<section class="card" style="grid-column:1/-1"><div class="editor-content"><h2 class="editor-title">Задача локального агента</h2><p class="section-note">'+escapeText(stateText)+'</p><p class="hint">'+escapeText(detail)+'</p>'+cancel+'<p class="hint">Отмена завершит текущий Blender-процесс и восстановит прежние выходные файлы задачи.</p></div></section>'
}
async function refreshAgentTask(){try{agentTask=await api('/api/agent-task')}catch(error){agentTask={state:'unavailable'}}finally{if(page==='Рендер')draw();clearTimeout(agentTaskTimer);agentTaskTimer=setTimeout(refreshAgentTask,2000)}}
async function cancelAgentTask(){if(!agentTask?.task_id||agentTask.state!=='running')return;try{agentTask=await api('/api/cancel-agent-task',{task_id:agentTask.task_id});notify('Остановка задачи агента запрошена');draw()}catch(error){notify(error.message,true)}}
function eventAction(target){const action=target.closest('[data-action]')?.dataset.action;if(!action)return false;switch(action){case'add-character':createCharacter();break;case'link-mia-reference':linkApprovedMiaReference();break;case'refresh-approved-references':refreshApprovedReferences();break;case'add-prop':createProp();break;case'add-scene':createScene();break;case'first':firstScene();break;case'prepare':prepare();break;case'save-octava-key':saveOctavaKey();break;case'save-octava-model':saveOctavaModel();break;case'save-mailbox-policy':saveMailboxPolicy();break;case'save-trusted-updates':saveTrustedUpdates();break;case'save-dropbox-review':saveDropboxReview();break;case'agent-toggle-pause':agentPause();break;case'agent-force-restart':agentRestart();break;case'telegram-route':telegramRoute();break;case'telegram-notify-toggle':telegramToggleNotifications();break;case'telegram-save':telegramSave();break;case'telegram-pair':telegramPair();break;case'telegram-test':telegramTest();break;case'delete-character':removeSelected('character');break;case'delete-prop':removeSelected('prop');break;case'delete-scene':removeSelected('scene');break;case'image-character':pendingImage={kind:'character',id:selectedCharacter};$('#imageFile').click();break;case'image-prop':pendingImage={kind:'prop',id:selectedProp};$('#imageFile').click();break;case'image-scene':pendingImage={kind:'scene',id:activeScene()?.id};$('#imageFile').click();break;case'render-demo':renderDemo();break;case'interpret-scene':interpretScene();break;case'render-scene':startStudioRender();break;case'cancel-scene':cancelStudioRender();break;case'cancel-agent-task':cancelAgentTask();break;case'assemble-project':assembleProject();break;case'load-text':loadScriptFile();break;default:return false}return true}
function loadScriptFile(){let picker=document.createElement('input');picker.type='file';picker.accept='.txt,text/plain';picker.onchange=async()=>{let file=picker.files[0];if(!file)return;if(file.size>30_000)return notify('Файл сценария должен быть не более 30 КБ.',true);let text=await file.text();if(text.length>4000)return notify('Текст должен быть не длиннее 4000 символов.',true);state.task=text.trim();markDirty();draw();notify('Сценарий загружен')};picker.click()}
function bindEditor(target){const ch=state.characters.find(x=>x.id===selectedCharacter),pr=state.props.find(x=>x.id===selectedProp),scene=activeScene();const fields=[['characterField',ch],['propField',pr],['sceneField',scene]];for(const [key,item] of fields){const field=target.dataset[key];if(field&&item){if(key==='sceneField')renderPlan=null;if(field==='duration'){const v=Number(target.value);if(!Number.isInteger(v)||v<1||v>120)return;item.duration=v}else item[field]=target.value;markDirty();return true}}const sf=target.dataset.setting;if(sf){renderPlan=null;if(sf==='duration'||sf==='fps'){const v=Number(target.value);if(!Number.isInteger(v)||v<1||v>(sf==='fps'?60:120))return true;state.settings[sf]=v;if(sf==='duration'&&scene)scene.duration=v}else{state.settings[sf]=target.value;if(scene&&['style','camera','animation'].includes(sf))scene[sf]=target.value}markDirty();return true}if(target.dataset.bind==='task'){state.task=target.value;$('#taskCounter')?.replaceChildren(document.createTextNode(`${state.task.length}/4000`));markDirty();return true}return false}
document.addEventListener('click',event=>{const a=event.target.closest('[data-action]');if(a){eventAction(a);return}const nav=event.target.closest('[data-nav]');if(nav){page=nav.dataset.nav;draw();if(page==='Паспорта'||page==='Персонажи')refreshApprovedReferences();if(page==='Настройки'){refreshOctavaStatus();refreshMailboxPolicy();refreshTrustedUpdates();refreshDropboxReview();refreshTelegramStatus();refreshAgentRuntime()}return}const ch=event.target.closest('[data-character]');if(ch){selectedCharacter=ch.dataset.character;page='Паспорта';draw();refreshApprovedReferences();return}const prop=event.target.closest('[data-prop]');if(prop){selectedProp=prop.dataset.prop;page='Реквизит';draw();return}const scene=event.target.closest('[data-scene]');if(scene){state.active_scene=scene.dataset.scene;renderPlan=null;page='Сцены';markDirty();draw()}});
document.addEventListener('input',event=>{if(event.target.id==='projectTitle'){state.title=event.target.value;markDirty();return}bindEditor(event.target)});
document.addEventListener('change',event=>{const t=event.target;if(t.id==='imageFile')return uploadImage();if(t.dataset.member){const scene=activeScene();if(!scene)return;renderPlan=null;const list=scene[t.dataset.member];if(t.checked&&!list.includes(t.value))list.push(t.value);else if(!t.checked)scene[t.dataset.member]=list.filter(id=>id!==t.value);markDirty();return}if(t.dataset.setting||t.dataset.sceneField)draw()});
$('#helpButton').addEventListener('click',()=>notify('Все данные хранятся локально. Сначала создай паспорта и реквизит, затем напиши задачу и нажми «Создать первую сцену».'));
window.addEventListener('beforeunload',event=>{if(dirty||saving){event.preventDefault();event.returnValue=''}});
(async()=>{try{state=await api('/api/state');selectedCharacter=state.characters[0]?.id||'';selectedProp=state.props[0]?.id||'';refreshAgentTask();try{const previous=await api('/api/studio-latest');studioJob=previous.job;if(studioJob&&(studioJob.state==='running'||studioJob.state==='queued'))pollStudioJob()}catch(e){}$('#savedStatus').textContent='✓ Локальный проект загружен';draw();refreshApprovedReferences()}catch(error){$('#main').innerHTML=`<div class="empty-message">Не удалось открыть проект. ${escapeText(error.message)}<br>Проверь журнал и перезагрузи страницу.</div>`;notify(error.message,true)}})();
